use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::Mutex;

// Kubernetes job worker for processing notification queue
// Deployed as a CronJob in the notifications namespace

#[derive(Clone, Debug)]
struct EmailMessage {
    to: String,
    subject: String,
    body: String,
    headers: HashMap<String, String>,
}

#[derive(Clone)]
struct SmtpConfig {
    host: String,
    port: u16,
    from_address: String,
}

struct NotificationWorker {
    smtp_config: SmtpConfig,
    queue: Arc<Mutex<Vec<JobPayload>>>,
}

#[derive(Clone, Debug)]
struct JobPayload {
    user_email: String,
    user_display_name: String,
    notification_type: String,
    template_vars: HashMap<String, String>,
}

/// RFC 5322 compliant header value encoder
/// Handles structured fields by folding long lines
fn encode_header_value(value: &str) -> String {
    // Encode using RFC 2047 for non-ASCII
    let needs_encoding = value.bytes().any(|b| b > 127);
    if needs_encoding {
        format!("=?UTF-8?B?{}?=", base64_encode(value.as_bytes()))
    } else {
        value.to_string()
    }
}

fn base64_encode(data: &[u8]) -> String {
    // Simple base64 encoding
    use std::fmt::Write;
    let alphabet = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut result = String::new();
    for chunk in data.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = if chunk.len() > 1 { chunk[1] as u32 } else { 0 };
        let b2 = if chunk.len() > 2 { chunk[2] as u32 } else { 0 };
        let triple = (b0 << 16) | (b1 << 8) | b2;
        write!(result, "{}", alphabet[((triple >> 18) & 0x3F) as usize] as char).unwrap();
        write!(result, "{}", alphabet[((triple >> 12) & 0x3F) as usize] as char).unwrap();
        if chunk.len() > 1 {
            write!(result, "{}", alphabet[((triple >> 6) & 0x3F) as usize] as char).unwrap();
        } else {
            result.push('=');
        }
        if chunk.len() > 2 {
            write!(result, "{}", alphabet[(triple & 0x3F) as usize] as char).unwrap();
        } else {
            result.push('=');
        }
    }
    result
}

/// Sanitizes the display name portion of an email address
/// Prevents injection through the display name field
fn sanitize_display_name(name: &str) -> String {
    // Remove characters that could break out of quoted-string context
    name.chars()
        .filter(|c| *c != '"' && *c != '\\')
        .collect()
}

/// Sanitizes any value that will be placed in an email header
/// Strips CR, LF, and null bytes to prevent header injection
fn sanitize_header_value(value: &str) -> String {
    value.chars()
        .filter(|c| *c != '\r' && *c != '\n' && *c != '\0')
        .collect()
}

/// Constructs the Reply-To header from user preferences
/// Uses structured address format: "Display Name" <email>
fn build_reply_to(display_name: &str, email: &str) -> String {
    let sanitized_name = sanitize_display_name(display_name);
    let sanitized_email = sanitize_header_value(email);
    format!("\"{}\" <{}>", sanitized_name, sanitized_email)
}

/// Validates email address format
fn is_valid_email(email: &str) -> bool {
    let parts: Vec<&str> = email.split('@').collect();
    if parts.len() != 2 {
        return false;
    }
    let local = parts[0];
    let domain = parts[1];
    // Also reject any CR/LF in email addresses
    let has_crlf = email.chars().any(|c| c == '\r' || c == '\n');
    !local.is_empty() && !domain.is_empty() && domain.contains('.') && local.len() <= 64 && domain.len() <= 255 && !has_crlf
}

impl NotificationWorker {
    fn new(smtp_config: SmtpConfig) -> Self {
        Self {
            smtp_config,
            queue: Arc::new(Mutex::new(Vec::new())),
        }
    }

    /// Process a single job from the queue
    /// Called by the k8s CronJob controller
    fn process_job(&self, payload: &JobPayload) -> Result<EmailMessage, String> {
        if !is_valid_email(&payload.user_email) {
            return Err("Invalid email address".to_string());
        }

        let subject = match payload.notification_type.as_str() {
            "welcome" => "Welcome to our platform!".to_string(),
            "password_reset" => "Password Reset Request".to_string(),
            "order_confirmation" => format!(
                "Order #{} Confirmed",
                payload.template_vars.get("order_id").unwrap_or(&"unknown".to_string())
            ),
            _ => "Notification".to_string(),
        };

        let body = self.render_template(payload)?;
        let mut headers = HashMap::new();

        // Add standard headers
        headers.insert("From".to_string(), self.smtp_config.from_address.clone());
        headers.insert("To".to_string(), payload.user_email.clone());
        // Sanitize the subject before encoding/insertion: it may contain
        // user-controlled template vars (e.g. order_id) that could carry CRLF.
        headers.insert("Subject".to_string(), encode_header_value(&sanitize_header_value(&subject)));
        headers.insert("MIME-Version".to_string(), "1.0".to_string());
        headers.insert("Content-Type".to_string(), "text/html; charset=UTF-8".to_string());

        // Set Reply-To based on notification context
        if let Some(reply_addr) = payload.template_vars.get("reply_to") {
            let reply_to = build_reply_to(&payload.user_display_name, reply_addr);
            headers.insert("Reply-To".to_string(), reply_to);
        }

        // Add custom tracking header for k8s observability
        if let Some(trace_id) = payload.template_vars.get("trace_id") {
            headers.insert("X-Trace-ID".to_string(), sanitize_header_value(trace_id));
        }

        Ok(EmailMessage {
            to: payload.user_email.clone(),
            subject,
            body,
            headers,
        })
    }

    fn render_template(&self, payload: &JobPayload) -> Result<String, String> {
        Ok(format!("<html><body><p>Hello, {}</p></body></html>", 
            html_escape(&payload.user_display_name)))
    }

    /// Serialize email to raw SMTP DATA format
    fn serialize_to_smtp(&self, msg: &EmailMessage) -> String {
        let mut raw = String::new();
        for (key, value) in &msg.headers {
            raw.push_str(&format!("{}: {}\r\n", key, value));
        }
        raw.push_str("\r\n");
        raw.push_str(&msg.body);
        raw
    }
}

fn html_escape(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_normal_notification() {
        let config = SmtpConfig {
            host: "smtp.internal.svc.cluster.local".to_string(),
            port: 587,
            from_address: "noreply@example.com".to_string(),
        };
        let worker = NotificationWorker::new(config);
        let mut vars = HashMap::new();
        vars.insert("order_id".to_string(), "12345".to_string());
        vars.insert("reply_to".to_string(), "support@example.com".to_string());
        vars.insert("trace_id".to_string(), "abc-123-def".to_string());

        let payload = JobPayload {
            user_email: "user@test.com".to_string(),
            user_display_name: "John Doe".to_string(),
            notification_type: "order_confirmation".to_string(),
            template_vars: vars,
        };

        let result = worker.process_job(&payload).unwrap();
        assert_eq!(result.to, "user@test.com");
    }

    #[test]
    fn test_injection_attempt_blocked() {
        let config = SmtpConfig {
            host: "smtp.internal.svc.cluster.local".to_string(),
            port: 587,
            from_address: "noreply@example.com".to_string(),
        };
        let worker = NotificationWorker::new(config);
        let mut vars = HashMap::new();
        vars.insert("reply_to".to_string(), "evil@attacker.com\r\nBcc: victim@example.com".to_string());
        vars.insert("trace_id".to_string(), "id\r\nX-Injected: true".to_string());

        let payload = JobPayload {
            user_email: "user@test.com".to_string(),
            user_display_name: "Test User".to_string(),
            notification_type: "welcome".to_string(),
            template_vars: vars,
        };

        let result = worker.process_job(&payload).unwrap();
        let smtp_output = worker.serialize_to_smtp(&result);
        // Verify no CRLF injection occurred
        for (key, value) in &result.headers {
            assert!(!value.contains('\r'), "Header {} contains CR", key);
            assert!(!value.contains('\n'), "Header {} contains LF", key);
        }
    }
}
